import os
import sys
import yaml
import logging
import json
from pathlib import Path
from typing import Dict, Any, List, Optional

from config import CONFIG
from utils.logging import get_logger

logger = get_logger(__name__)

def load_checksums(checksums_path: Path) -> Dict[str, str]:
    """Load the checksums.txt file generated by T019."""
    checksums = {}
    if not checksums_path.exists():
        logger.warning(f"Checksums file not found at {checksums_path}. Skipping update.")
        return checksums

    with open(checksums_path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            # Format: <hash>  <filename>
            parts = line.split()
            if len(parts) >= 2:
                # Handle paths with spaces if any, though typically single path
                # Standard sha256sum output: hash  filename
                file_hash = parts[0]
                file_path = ' '.join(parts[1:])
                checksums[file_path] = file_hash
    return checksums

def load_or_create_state(state_path: Path) -> Dict[str, Any]:
    """Load existing state file or create a new structure."""
    if state_path.exists():
        with open(state_path, 'r', encoding='utf-8') as f:
            try:
                return yaml.safe_load(f) or {}
            except yaml.YAMLError as e:
                logger.error(f"Failed to parse existing state file: {e}")
                return {}
    
    # Create new state structure
    state = {
        "project_id": "PROJ-537-predicting-the-yield-strength-of-bcc-ste",
        "version": "1.0.0",
        "last_updated": None,
        "artifacts": {}
    }
    return state

def update_state_with_checksums(
    state: Dict[str, Any], 
    checksums: Dict[str, str], 
    project_root: Path
) -> Dict[str, Any]:
    """Update the state dictionary with artifact hashes from checksums."""
    from datetime import datetime

    if not checksums:
        logger.warning("No checksums provided to update state.")
        return state

    artifacts = state.get("artifacts", {})
    
    for rel_path, file_hash in checksums.items():
        # Ensure the path is relative to project root for consistency
        # If the checksum file contains absolute paths or paths relative to data/, normalize them.
        # Assuming checksums.txt contains paths relative to project root or data/
        full_path = project_root / rel_path
        if not full_path.exists():
            # Try if the path in checksums was relative to data/ specifically
            # This handles cases where T019 might have written relative to data/
            alt_path = project_root / "data" / rel_path
            if alt_path.exists():
                full_path = alt_path
            else:
                logger.warning(f"Artifact path in checksums not found: {rel_path}")
                continue

        # Normalize path for storage (relative to project root)
        normalized_path = str(full_path.relative_to(project_root))
        
        artifacts[normalized_path] = {
            "sha256": file_hash,
            "last_verified": datetime.utcnow().isoformat() + "Z"
        }
    
    state["artifacts"] = artifacts
    state["last_updated"] = datetime.utcnow().isoformat() + "Z"
    return state

def save_state(state: Dict[str, Any], state_path: Path) -> None:
    """Save the updated state to YAML."""
    state_path.parent.mkdir(parents=True, exist_ok=True)
    
    with open(state_path, 'w', encoding='utf-8') as f:
        yaml.dump(state, f, default_flow_style=False, sort_keys=False, allow_unicode=True)
    
    logger.info(f"State file updated successfully at {state_path}")

def main() -> int:
    """Main entry point for T020: Update state with artifact hashes."""
    project_root = CONFIG.PROJECT_ROOT
    checksums_path = CONFIG.CHECKSUMS_FILE
    state_path = CONFIG.STATE_FILE

    logger.info(f"Starting state update for project: {CONFIG.PROJECT_ID}")
    logger.info(f"Loading checksums from: {checksums_path}")
    logger.info(f"Target state file: {state_path}")

    # Load checksums generated by T019
    checksums = load_checksums(checksums_path)
    
    if not checksums:
        logger.warning("No checksums found. State file will be created/updated with empty artifacts.")
    
    # Load or create state
    state = load_or_create_state(state_path)
    
    # Ensure project ID is correct
    state["project_id"] = CONFIG.PROJECT_ID

    # Update with hashes
    state = update_state_with_checksums(state, checksums, project_root)

    # Save
    save_state(state, state_path)

    logger.info("State update completed.")
    return 0

if __name__ == "__main__":
    sys.exit(main())
